function splitLine(line) {
    const res = []; let cur = ''; let inQ = false;
    for (let i = 0; i < line.length; i++) {
        if (line[i] === '"') { inQ = !inQ; }
        else if (line[i] === ',' && !inQ) { res.push(cur.trim()); cur = ''; }
        else cur += line[i];
    }
    res.push(cur.trim());
    return res;
}

